INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-quantjourney-o01-market-sma-cross', 'quantjourney-o01-market-sma-cross', 'QuantJourney O01: Market SMA Crossover', 'QuantJourney example O01 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: buy about 18% of equity at market when SMA 20 moves above SMA 50; sell all at market when it moves back below. QuantJourney published: total return 126.7%, Sharpe 0.21, max drawdown -16.4%. QuantJourney engine on Vertex Yahoo data: total return 126.7%, Sharpe 0.21, max drawdown -16.3% (within tolerance). Vertex re-run (Vertex DSL signal engine, 10 bp per side): CAGR 5.5%, Sharpe 0.48, max drawdown -28.8%; deflated Sharpe probability 0.02 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-01-market-sma-cross GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_01_market_sma_cross.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "vertex-dsl", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o02-market-rsi-reversion', 'quantjourney-o02-market-rsi-reversion', 'QuantJourney O02: Market RSI Reversion', 'QuantJourney example O02 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: buy about 12% of equity at market while RSI 14 is below 35; sell all when RSI 14 rises above 60. QuantJourney published: total return 29.1%, Sharpe -0.17, max drawdown -16.0%. QuantJourney engine on Vertex Yahoo data: total return 29.1%, Sharpe -0.17, max drawdown -16.0% (within tolerance). Vertex re-run (Vertex DSL signal engine, 10 bp per side): CAGR 2.3%, Sharpe 0.23, max drawdown -43.5%; deflated Sharpe probability 0.00 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-02-market-rsi-reversion GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_02_market_rsi_reversion.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "meanrev", "vertex-dsl", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o03-limit-rsi-dip', 'quantjourney-o03-limit-rsi-dip', 'QuantJourney O03: Limit RSI Dip Buyer', 'QuantJourney example O03 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: when RSI 14 is below 40, place a buy limit 1.5% under the close (valid 3 bars); once long, place a sell limit 3% over the average entry (valid 3 bars). QuantJourney published: total return 94.7%, Sharpe 0.14, max drawdown -19.1%. QuantJourney engine on Vertex Yahoo data: total return 94.4%, Sharpe 0.14, max drawdown -19.1% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 2.7%, Sharpe 0.44, max drawdown -19.1%; deflated Sharpe probability 0.01 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-03-limit-rsi-dip GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_03_limit_rsi_dip.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "meanrev", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o04-limit-trend-pullback', 'quantjourney-o04-limit-trend-pullback', 'QuantJourney O04: Limit Trend Pullback', 'QuantJourney example O04 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: when the close is above SMA 50, place a buy limit 1% under the close (valid 2 bars); take profit with a sell limit 4% over entry; sell at market if the close falls under SMA 50. QuantJourney published: total return 56.8%, Sharpe -0.04, max drawdown -6.8%. QuantJourney engine on Vertex Yahoo data: total return 59.1%, Sharpe -0.02, max drawdown -6.8% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 1.6%, Sharpe 0.47, max drawdown -7.2%; deflated Sharpe probability 0.02 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-04-limit-trend-pullback GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_04_limit_trend_pullback.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o05-stop-breakout-entry', 'quantjourney-o05-stop-breakout-entry', 'QuantJourney O05: Stop Breakout Entry', 'QuantJourney example O05 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: place a buy stop 0.2% over the highest close of the prior 20 bars (valid 5 bars); sell at market 10 bars after the fill. QuantJourney published: total return 41.4%, Sharpe -0.19, max drawdown -10.5%. QuantJourney engine on Vertex Yahoo data: total return 42.2%, Sharpe -0.18, max drawdown -10.5% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 1.1%, Sharpe 0.38, max drawdown -11.9%; deflated Sharpe probability 0.01 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-05-stop-breakout-entry GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_05_stop_breakout_entry.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "breakout", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o06-stop-loss-protection', 'quantjourney-o06-stop-loss-protection', 'QuantJourney O06: Protective Stop Loss', 'QuantJourney example O06 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: buy about 15% of equity at market when SMA 20 moves above SMA 50; attach a stop 5% under entry; sell at market when SMA 20 moves back below SMA 50. QuantJourney published: total return 60.1%, Sharpe 0.00, max drawdown -16.2%. QuantJourney engine on Vertex Yahoo data: total return 60.1%, Sharpe 0.00, max drawdown -16.2% (within tolerance). Vertex re-run (Vertex DSL signal engine, 10 bp per side): CAGR 3.7%, Sharpe 0.38, max drawdown -32.0%; deflated Sharpe probability 0.01 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-06-stop-loss-protection GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_06_stop_loss_protection.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "vertex-dsl", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o07-stop-limit-breakout', 'quantjourney-o07-stop-limit-breakout', 'QuantJourney O07: Stop-Limit Breakout', 'QuantJourney example O07 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: buy stop 0.2% over the prior 20-bar high with a limit 0.4% over the stop (valid 5 bars), so a gap can leave it unfilled; sell at market 12 bars after the fill. QuantJourney published: total return 56.2%, Sharpe -0.05, max drawdown -6.4%. QuantJourney engine on Vertex Yahoo data: total return 57.6%, Sharpe -0.04, max drawdown -6.4% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 1.5%, Sharpe 0.51, max drawdown -7.1%; deflated Sharpe probability 0.03 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-07-stop-limit-breakout GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_07_stop_limit_breakout.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "breakout", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o08-stop-limit-protection', 'quantjourney-o08-stop-limit-protection', 'QuantJourney O08: Stop-Limit Protection', 'QuantJourney example O08 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: As O06, but the protective exit is a stop-limit (stop 4% under entry, limit 4.5% under entry), which can stay unfilled after a gap. QuantJourney published: total return 63.6%, Sharpe 0.02, max drawdown -14.2%. QuantJourney engine on Vertex Yahoo data: total return 63.6%, Sharpe 0.02, max drawdown -14.2% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 1.9%, Sharpe 0.41, max drawdown -14.5%; deflated Sharpe probability 0.01 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-08-stop-limit-protection GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_08_stop_limit_protection.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o09-trailing-stop-trend', 'quantjourney-o09-trailing-stop-trend', 'QuantJourney O09: Trailing Stop Trend', 'QuantJourney example O09 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: SMA 20/50 trend entry at market; exit with a 4% trailing stop or at market on the reverse cross. QuantJourney published: total return 30.0%, Sharpe -0.33, max drawdown -7.0%. QuantJourney engine on Vertex Yahoo data: total return 30.0%, Sharpe -0.33, max drawdown -7.0% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 0.9%, Sharpe 0.36, max drawdown -7.4%; deflated Sharpe probability 0.00 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-09-trailing-stop-trend GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_09_trailing_stop_trend.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o10-trailing-stop-rsi', 'quantjourney-o10-trailing-stop-rsi', 'QuantJourney O10: RSI + Trailing Stop', 'QuantJourney example O10 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: buy at market when RSI 14 is below 38; exit with a 5% trailing stop or at market when RSI 14 is above 65. QuantJourney published: total return -12.2%, Sharpe -0.41, max drawdown -39.0%. QuantJourney engine on Vertex Yahoo data: total return -12.1%, Sharpe -0.41, max drawdown -39.0% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR -0.8%, Sharpe -0.12, max drawdown -41.2%; deflated Sharpe probability 0.00 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-10-trailing-stop-rsi GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_10_trailing_stop_rsi.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "meanrev", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o11-trailing-stop-limit', 'quantjourney-o11-trailing-stop-limit', 'QuantJourney O11: Trailing Stop-Limit', 'QuantJourney example O11 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: As O09, but the trailing exit is a trailing stop-limit (trail 4% of the close, limit 0.5% under the stop). QuantJourney published: total return 28.1%, Sharpe -0.38, max drawdown -6.2%. QuantJourney engine on Vertex Yahoo data: total return 28.8%, Sharpe -0.37, max drawdown -6.2% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 0.9%, Sharpe 0.36, max drawdown -6.5%; deflated Sharpe probability 0.00 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-11-trailing-stop-limit GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_11_trailing_stop_limit.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o12-bracket-trend', 'quantjourney-o12-bracket-trend', 'QuantJourney O12: Bracket Trend', 'QuantJourney example O12 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: on the SMA 20/50 up-cross, buy at market with a bracket: take profit 6% and stop 3% from the signal close; sell at market on the reverse cross. QuantJourney published: total return 29.4%, Sharpe -0.38, max drawdown -6.8%. QuantJourney engine on Vertex Yahoo data: total return 29.4%, Sharpe -0.38, max drawdown -6.8% (within tolerance). Vertex re-run (Vertex DSL signal engine, 10 bp per side): CAGR 2.3%, Sharpe 0.47, max drawdown -15.5%; deflated Sharpe probability 0.02 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-12-bracket-trend GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_12_bracket_trend.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "trend", "vertex-dsl", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o13-bracket-rsi-reversion', 'quantjourney-o13-bracket-rsi-reversion', 'QuantJourney O13: Bracket RSI Reversion', 'QuantJourney example O13 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF: buy when RSI 14 is below 35 with a bracket: take profit 4% and stop 2% from the signal close; sell at market when RSI 14 is above 70. QuantJourney published: total return 8.5%, Sharpe -0.43, max drawdown -11.6%. QuantJourney engine on Vertex Yahoo data: total return 8.5%, Sharpe -0.43, max drawdown -11.6% (within tolerance). Vertex re-run (Vertex DSL signal engine, 10 bp per side): CAGR -1.0%, Sharpe -0.11, max drawdown -35.6%; deflated Sharpe probability 0.00 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-13-bracket-rsi-reversion GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_13_bracket_rsi_reversion.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "meanrev", "vertex-dsl", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o14-oco-dip-or-breakout', 'quantjourney-o14-oco-dip-or-breakout', 'QuantJourney O14: OCO Dip or Breakout', 'QuantJourney example O14 (orders, 1d bars, Equity ETFs: SPY, QQQ, IWM; 2001-01-03 to 2026-01-01). Rules: Per ETF, every 5th bar while flat: a one-cancels-other pair of a buy limit 2% under and a buy stop 2% over the close (valid 5 bars); sell at market 10 bars after the fill. QuantJourney published: total return 45.5%, Sharpe -0.08, max drawdown -13.2%. QuantJourney engine on Vertex Yahoo data: total return 44.7%, Sharpe -0.09, max drawdown -13.1% (within tolerance). Vertex re-run (adapter, 10 bp per side): CAGR 1.2%, Sharpe 0.28, max drawdown -13.7%; deflated Sharpe probability 0.00 with 50 trials; gates: fail. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-14-oco-dip-or-breakout GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_14_oco_dip_or_breakout.py Research only.', 'external', 'backtested', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "1d", "breakout", "meanrev", "reproduced"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o15-intraday-5m-bracket-reversion', 'quantjourney-o15-intraday-5m-bracket-reversion', 'QuantJourney O15: Intraday 5m Bracket Reversion', 'QuantJourney example O15 (orders, 5m bars, Equity ETFs: SPY, QQQ, IWM; 2026-06-10 to 2026-07-11). Rules: 5-minute bars: buy when RSI 14 is below 30 with a bracket of +0.6% take profit and -0.4% stop. QuantJourney published: total return 1.1%, Sharpe n/a, max drawdown -1.3%. Not re-run: Yahoo serves 5-minute bars only for the last 60 days (checked 2026-10-31); the published window 2026-06-10 to 2026-07-11 is outside it, and Vertex stores no intraday history. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-15-intraday-5m-bracket-reversion GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_15_intraday_5m_bracket_reversion.py Research only.', 'external', 'idea', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "5m", "meanrev", "needs-data"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
  ('strategy-seed-quantjourney-o16-intraday-30m-stop-breakout', 'quantjourney-o16-intraday-30m-stop-breakout', 'QuantJourney O16: Intraday 30m Stop Breakout', 'QuantJourney example O16 (orders, 30m bars, Equity ETFs: SPY, QQQ, IWM; 2026-05-18 to 2026-07-10). Rules: 30-minute bars: buy stop over the prior 12-bar high (valid 3 bars); sell at market after a fixed number of bars. QuantJourney published: total return -13.9%, Sharpe n/a, max drawdown -14.8%. Not re-run: Yahoo serves 30-minute bars only for the last 60 days (checked 2026-10-31); the published window 2026-05-18 to 2026-07-10 is outside it, and Vertex stores no intraday history. Details: docs/vertex-rebuild/quantjourney-library.md. Dashboard: https://backtester.quantjourney.cloud/strategies/example-orders-16-intraday-30m-stop-breakout GitHub: https://github.com/QuantJourneyOrg/quantjourney-bt/blob/4f403d853833e1daa6de01c5b6c6cb3983dc0044/strategies/example_orders_16_intraday_30m_stop_breakout.py Research only.', 'external', 'idea', 'research/backtests/quantjourney/library.json', '["quantjourney", "orders", "30m", "breakout", "needs-data"]'::jsonb, 'QuantJourney orders', '[]'::jsonb),
